const query=new URLSearchParams(location.search);
let page=query.get('page')||'overview';
const left=document.querySelector('#left-page');
const right=document.querySelector('#right-page');
const slips=document.querySelector('#page-slips');
const picker=document.querySelector('#portrait-picker');
const screen=document.querySelector('#screen');
const portrait=n=>`style="--px:${n%3*50}%;--py:${Math.floor(n/3)*100}%"`;
const row=(name,rank,where,action,n,selected=false,warn=false)=>`<button class="person-row ${selected?'selected':''}" type="button" data-go="${name==='顾闻舟'?'peaks':'overview'}"><span class="avatar" ${portrait(n)}></span><span class="who"><b>${name}</b><small>${rank} · ${where}</small></span><span class="current ${warn?'warn':''}">${action}</span></button>`;
const leftRoster=expanded=>`<div class="folio-kicker">云岫山门 · 正式门籍</div><h1 class="folio-title">门人志</h1><p class="folio-subtitle">${expanded?'分峰 · 现籍五人':'开山旧院 · 现籍二人'}</p><div class="ornament"></div><div class="roster-head">主峰 <small>${expanded?'二人':'二人'}</small></div>${row('陆知微','内门','主峰','整理药箱',1,!expanded)}${row('林长风','外门','主峰','搬运旧木',2)}${expanded?`<div class="roster-head">丹霞峰 <small>三人</small></div>${row('顾闻舟','内门','丹霞峰','丹房候料',3,true,true)}${row('晏清禾','外门','丹霞峰','修习入门法',5)}${row('柳观澜','亲传','丹霞峰','传授药理',4)}`:`<div class="roster-hint"><b>门人近况</b><br>林长风今日搬运旧木，陆知微正在整理药箱。选中人物可查看其当前行动和已知缘由。</div>`}<p class="ranking-note">现籍只记正式入门之人；失联与离宗记录由卷末旧录保存。</p>`;
const personHead=(name,portraitIndex,subtitle,badges)=>`<div class="person-head"><div class="large-avatar" ${portrait(portraitIndex)}></div><div class="identity"><small>云岫山门 · 人物卷册</small><h2>${name}</h2><p>${subtitle}</p>${badges.map(x=>`<span class="meta-chip">${x}</span>`).join('')}</div></div><div class="ornament"></div>`;
const luHead=()=>personHead('陆知微',1,'十七岁 · 炼气三层 · 木灵根已验录',['主峰内门','师承沈砚']);
const guHead=()=>personHead('顾闻舟',3,'二十七岁 · 炼气七层 · 丹道见长',['丹霞峰内门','丹师']);
const rightOverview=()=>`${luHead()}<div class="section-head">此刻所见 <small>卯时 · 山院亲见</small></div><div class="calm-panel">在主屋前廊整理药箱，稍后准备照料院边灵草。</div><div class="status-card"><span class="label">身体</span><strong>精神尚可；旧伤需继续调养<small>已知伤势，今晨观察</small></strong></div><div class="status-card"><span class="label">眼下受阻</span><strong>药圃尚未修成，照料工作只能在院边进行<small>设施现状</small></strong></div><div class="status-card"><span class="label">本人打算</span><strong>先备药，再向掌门请教草木之法<small>本人所述 · 昨日</small></strong></div><div class="action-row"><button class="brush-button secondary" type="button">与她交谈</button><button class="brush-button" type="button">山院定位</button></div>`;
const rightDuties=()=>`${luHead()}<div class="section-head">门籍与师承 <small>可核对的宗门记录</small></div><div class="status-card"><span class="label">入门</span><strong>主峰 · 内门<small>三月初五 · 掌门主持收录</small></strong></div><div class="status-card"><span class="label">师父</span><strong>沈砚<small>亲授关系已成立；授业仍按实际课程进行</small></strong></div><div class="status-card"><span class="label">职务</span><strong>尚无宗门职务<small>日常帮忙不等于受任执事</small></strong></div><div class="section-head">事务与承诺</div><div class="mini-panel"><b>已答应的差事</b>整理旧院药箱，照料院边灵草。<br><span class="micro">本人同意 · 今日卯时起</span></div><div class="status-card"><span class="label">下一步</span><strong>若要长期负责药圃，须先完成营造并征得本人同意。</strong></div><div class="action-row"><button class="brush-button secondary" type="button">查看营造</button><button class="brush-button" type="button">提出差事</button></div>`;
const rightCultivation=()=>`${luHead()}<div class="section-head">修为与适性 <small>已知内容</small></div><div class="two-column"><div class="mini-panel"><b>炼气三层</b>本层修为积累约六成<div class="progress" style="margin-top:11px"><i style="width:62%"></i></div></div><div class="mini-panel"><b>木灵根</b>亲水木之气；其他适性尚无可靠判断。<span class="source">入门验录</span></div></div><div class="section-head">所习传承</div><div class="status-card"><span class="label">主修</span><strong>青木调息法<small>已获授入门篇；本人正在练习</small></strong></div><div class="status-card"><span class="label">理解</span><strong>可独自运转入门周天<small>尚未证实能向他人授课</small></strong></div><div class="status-card"><span class="label">眼下阻碍</span><strong>药理篇尚无可靠完整版本<small>开放典籍或安排授业，仍由她自行选择</small></strong></div><div class="action-row"><button class="brush-button secondary" type="button">查看典籍</button><button class="brush-button" type="button">邀约授业</button></div>`;
const rightRelations=()=>`${luHead()}<div class="section-head">志向与交情 <small>以掌门已知为准</small></div><div class="calm-panel">“我想把草木之学练成真本事，让山院往后有药可用。”<span class="source">本人所述 · 三月初五</span></div><div class="relationship"><span>沈砚 · 师父</span><small>已拜师；曾获授调息法</small></div><div class="relationship"><span>林长风 · 同门</span><small>今晨一同整理旧院</small></div><div class="section-head">重要纪事 <small>按获知时间记录</small></div><div class="timeline"><div class="event"><time>三月初五 · 亲见</time><b>在山门正式入宗，归主峰内门。</b><span>师承沈砚；门籍当日落定。</span></div><div class="event"><time>三月初六 · 本人所述</time><b>愿意照料旧院灵草。</b><span>希望以后能学习更完整的药理传承。</span></div><div class="event"><time>三月初八 · 山院亲见</time><b>整理药箱，准备照料院边灵草。</b></div></div><div class="action-row"><button class="brush-button" type="button">与她交谈</button></div>`;
const rightPeaks=()=>`${guHead()}<div class="alert">丹房已备炉，缺一味灵草；本轮炼丹尚未开始。</div><div class="section-head">此刻所见 <small>辰时 · 丹霞峰来报</small></div><div class="status-card"><span class="label">所在</span><strong>丹霞峰丹房<small>丹房执事来报 · 辰时</small></strong></div><div class="status-card"><span class="label">正在做</span><strong>核对药材并等候送达<small>尚未投入丹炉，也未开始结算</small></strong></div><div class="status-card"><span class="label">师承</span><strong>柳观澜<small>个人师徒关系</small></strong></div><div class="status-card"><span class="label">职务</span><strong>丹师<small>宗门任职，与内门身份分别记录</small></strong></div><div class="section-head">可以回应</div><div class="mini-panel">查询药材所在、调配供给，或与本人商议改做其他事务。</div><div class="action-row"><button class="brush-button secondary" type="button">查看丹房</button><button class="brush-button" type="button">查药材</button></div>`;
const leftLargeRoster=()=>`<div class="folio-kicker">云岫山门 · 正式门籍</div><h1 class="folio-title">门人志</h1><p class="folio-subtitle">现籍一百三十八人 · 按归属翻卷</p><div class="ornament"></div><div class="attention-strip"><b>需掌门留意 · 七人</b><span>伤病二 · 差事受阻三 · 去向待核二</span></div><div class="section-head">各峰门籍 <small>人数为现籍，红印为待照应</small></div><div class="peak-entry"><span class="peak-mark">主</span><span class="peak-name"><b>主峰</b><small>掌门直属 · 三十四人</small></span><span class="peak-count">34 <i>2</i></span></div><div class="peak-entry selected"><span class="peak-mark">丹</span><span class="peak-name"><b>丹霞峰</b><small>丹药与草木 · 二十九人</small></span><span class="peak-count">29 <i>3</i></span></div><div class="peak-entry"><span class="peak-mark">东</span><span class="peak-name"><b>东峰</b><small>二十六人</small></span><span class="peak-count">26 <i>1</i></span></div><div class="peak-entry"><span class="peak-mark">西</span><span class="peak-name"><b>西峰</b><small>二十五人</small></span><span class="peak-count">25 <i>1</i></span></div><div class="peak-entry"><span class="peak-mark">北</span><span class="peak-name"><b>北峰</b><small>二十四人</small></span><span class="peak-count">24</span></div><p class="large-roster-foot">离宗、身故及旧师承另存卷末，不计入现籍。</p>`;
const rosterLine=(name,rank,work,where,n,attention='')=>`<button class="large-person-row" type="button" data-go="peaks"><span class="avatar" ${portrait(n)}></span><span class="person-main"><b>${name}</b><small>${rank} · ${work}</small></span><span class="person-state ${attention?'need-attention':''}">${attention||where}</span></button>`;
const rightLargeRoster=()=>`<div class="folio-kicker">门人志 · 分峰索引</div><h2 class="folio-title">丹霞峰</h2><p class="folio-subtitle">现籍二十九人 · 峰主柳观澜 · 本峰可收徒</p><div class="ornament"></div><div class="roster-tools"><span class="search-ink">⌕&nbsp; 寻名</span><span class="filter-stamp on">全部 29</span><span class="filter-stamp">外门 16</span><span class="filter-stamp">内门 10</span><span class="filter-stamp">亲传 3</span></div><div class="roster-subtools"><span>按姓名阅览</span><strong>待照应 3 · 任职 8</strong></div><div class="large-person-list">${rosterLine('白芷宁','外门','药圃学徒','药圃',0)}${rosterLine('顾闻舟','内门','丹师','丹房',3,'炼丹受阻')}${rosterLine('胡听雨','外门','灵草采集','外出',5)}${rosterLine('江雪青','内门','药圃执事','药圃',1)}${rosterLine('柳观澜','亲传','峰主','授课',4)}${rosterLine('秦溪','外门','草木研习','藏经阁',2)}${rosterLine('沈怀素','内门','药师','医庐',1,'旧伤待诊')}${rosterLine('晏清禾','外门','传承研习','修行',5)}</div><div class="roster-pagination"><span>第 1 / 4 页</span><button type="button">上一页</button><button type="button">下一页 ›</button></div>`;
const leftPetition=()=>`<div class="folio-kicker">山门 · 一次求入门记录</div><h1 class="folio-title">拜山求见</h1><p class="folio-subtitle">山门石阶 · 秦溪</p><div class="ornament"></div><div class="petition-portrait" ${portrait(5)}></div><div class="status-card"><span class="label">年岁</span><strong>十六<small>本人自报</small></strong></div><div class="status-card"><span class="label">灵根</span><strong>木灵根<small>入门验录</small></strong></div><div class="status-card"><span class="label">来历</span><strong>自青木镇而来<small>本人所述；细节尚待核实</small></strong></div><p class="ranking-note">掌门需当面询问并据已知信息判断，此时尚无门籍。</p>`;
const rightPetition=()=>`<div class="folio-kicker">山门当面择徒</div><h2 class="folio-title">秦溪所求</h2><p class="folio-subtitle">想求一门可修之法，愿从照料药草学起</p><div class="ornament"></div><div class="section-head">当前了解 <small>本人所述 · 尚待辨明</small></div><div class="calm-panel">曾帮家中照看药圃，识得几种常见草药；此前师承与来历未能核定。</div><div class="section-head">拟授身份</div><div class="rank-options"><span class="on">外门</span><span>内门</span><span>亲传</span></div><div class="status-card"><span class="label">归属</span><strong>主峰<small>正式收录时确定</small></strong></div><div class="status-card"><span class="label">收录核对</span><strong>归属峰收徒权限、宗门容量、住居与本人意愿<small>亲传另须具体师父确认</small></strong></div><div class="action-row"><button class="brush-button secondary" type="button">婉谢求见</button><button class="brush-button" type="button">核对收录</button></div><p class="ranking-note">未作决定时仍是求见流程；正式收下后才记外门、内门或亲传。</p>`;
function render(){
  if(!['overview','duties','cultivation','relations','peaks','roster-large','petition'].includes(page))page='overview';
  screen.dataset.page=page;
  const mature=page==='peaks'||page==='roster-large';
  document.querySelector('.resource-bar b').textContent=mature?'八月初八 · 辰时':'三月初八 · 卯时';
  document.querySelector('.game-logo span').textContent=mature?'云岫山门 · 道火不熄':'云岫旧院 · 道火不熄';
  const mainPage=['overview','duties','cultivation','relations'].includes(page);
  left.innerHTML=page==='roster-large'?leftLargeRoster():page==='petition'?leftPetition():leftRoster(page==='peaks');
  right.innerHTML=({overview:rightOverview,duties:rightDuties,cultivation:rightCultivation,relations:rightRelations,peaks:rightPeaks,'roster-large':rightLargeRoster,petition:rightPetition})[page]();
  slips.innerHTML=(page==='roster-large'?['roster-large','peaks','overview']:mainPage?['overview','duties','cultivation','relations']:page==='peaks'?['roster-large','peaks','overview']:['petition','overview','roster-large']).map(p=>`<button type="button" data-go="${p}" class="${p===page?'active':''}">${({overview:'卷首',duties:'门籍事务',cultivation:'修行传承',relations:'人情纪事',peaks:'人物卷', 'roster-large':'分峰名册',petition:'山门求见'})[p]}</button>`).join('');
  picker.innerHTML=page==='peaks'?`<strong>丹霞峰 · 现籍三人</strong><span class="avatar active" ${portrait(3)}></span><span class="avatar" ${portrait(5)}></span><span class="avatar" ${portrait(4)}></span>`:`<strong>主峰 · 现籍二人</strong><span class="avatar active" ${portrait(1)}></span><span class="avatar" ${portrait(2)}></span>`;
  document.querySelector('.ruined-hall').style.display=mature?'none':'';
  document.querySelector('.scene-plaque').textContent=mature?'云岫山域 · 分峰阶段':'云岫旧院 · 门人系统';
  document.querySelectorAll('.game-rail button').forEach(b=>b.classList.toggle('active',b.dataset.go===(page==='roster-large'?'roster-large':'overview')));
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-go]');if(!b)return;page=b.dataset.go;history.replaceState(null,'',`?page=${page}`);render()});
render();
